if 'id="zoombox"' not in (M / "index.html").read_text(encoding="utf-8"):
    sys.exit("Run patch_list_0917.py first. Nothing was written.")
if "function addWorldButton" in (M / "app.js").read_text(encoding="utf-8"):
    sys.exit("Already applied — nothing to do.")

out = {}
for name, pairs in PAIRS.items():
    t = (M / name).read_text(encoding="utf-8")
    for old, new in pairs:
        if t.count(old) != 1:
            sys.exit(f"Could not find the expected text in map/{name} ({old.strip()[:70]!r}). Nothing was written.")
        t = t.replace(old, new)
    out[name] = t
for name, t in out.items():
    (M / name).write_text(t, encoding="utf-8")
print("Done: whole-world button, terrain on a round Earth, tilt, turn and roll.")
